method mentor_m(Managers: array<int>, StartYears: array2<int>) returns (avgDiff: real)
  requires Managers.Length > 0 && StartYears.Length0 > 0 && StartYears.Length1 > 0
  requires Managers.Length == StartYears.Length0
  // Each manager has exactly one start year
  requires forall i | 0 <= i < StartYears.Length0 :: StartYears.Length1 == 1
  // All start years are distinct
  requires forall i, j | 0 <= i < Managers.Length && 0 <= j < Managers.Length && i != j :: 
    StartYears[i, 0] != StartYears[j, 0]
{
  // First, we need to sort managers by their start years
  // Create a copy of indices to sort
  var indices := new int[Managers.Length];
  var i := 0;
  while i < Managers.Length
    invariant 0 <= i <= Managers.Length
    invariant forall k | 0 <= k < i :: 0 <= indices[k] < Managers.Length
  {
    indices[i] := i;
    i := i + 1;
  }

  // Simple bubble sort to sort indices by start years
  var sorted := false;
  while !sorted
    invariant forall k | 0 <= k < Managers.Length :: 0 <= indices[k] < Managers.Length
    decreases Managers.Length * Managers.Length
  {
    sorted := true;
    var j := 0;
    while j < Managers.Length - 1
      invariant 0 <= j <= Managers.Length - 1
      invariant forall k | 0 <= k < Managers.Length :: 0 <= indices[k] < Managers.Length
    {
      if StartYears[indices[j], 0] > StartYears[indices[j + 1], 0] {
        // Swap
        var temp := indices[j];
        indices[j] := indices[j + 1];
        indices[j + 1] := temp;
        sorted := false;
      }
      j := j + 1;
    }
  }

  // Now calculate total difference between consecutive managers in sorted order
  var totalDiff := 0;
  var count := 0;

  i := 0;
  while i < Managers.Length - 1
    invariant 0 <= i <= Managers.Length - 1
    invariant totalDiff >= 0
    invariant count == i
  {
    var currentIndex := indices[i];
    var nextIndex := indices[i + 1];

    // Calculate difference in start years (mentor has higher start year)
    var diff := StartYears[nextIndex, 0] - StartYears[currentIndex, 0];
    totalDiff := totalDiff + diff;
    count := count + 1;

    i := i + 1;
  }

  // Calculate average difference
  if count > 0 {
    avgDiff := totalDiff as real / count as real;
  } else {
    avgDiff := 0.0;
  }
}

// Helper function to check if mentors have higher start years than mentees
function ValidMentorPairs(StartYears: array2<int>): bool
  requires StartYears != null
  requires StartYears.Length0 > 0 && StartYears.Length1 > 0
{
  // Check that for any pair where i < j, StartYears[i, 0] < StartYears[j, 0]
  // This ensures mentors (with higher indices after sorting) have higher start years
  forall i, j {:trigger StartYears[i, 0]; :trigger StartYears[j, 0]} | 0 <= i < j < StartYears.Length0 :: 
    StartYears[i, 0] < StartYears[j, 0]
}

