  requires forall i, j :: 0 <= i < A.Length0 && 0 <= j < A.Length1 ==> 0 <= A[i, j]  // all elements non-negative initially
  requires forall i, j :: 0 <= i < A.Length0 && 0 <= j < A.Length1-1 ==> A[i, j] <= A[i, j+1]  // rows are non-decreasing initially
  modifies A
  ensures forall i, j :: 0 <= i < A.Length0 && 0 <= j < A.Length1 ==> 0 <= A[i, j]  // all elements non-negative after
  ensures forall i, j :: 0 <= i < A.Length0 && 0 <= j < A.Length1-1 ==> A[i, j] <= A[i, j+1]  // rows remain non-decreasing
  ensures forall i, j :: 0 <= i < A.Length0 && 0 <= j < A.Length1 ==> A[i, j] == old(A[i, j]) + 1  // each element is incremented by 1
{
